<?php
require_once __DIR__.'/core.php';require_once __DIR__.'/ad_lib.php';tt_require_login();if($_SERVER['REQUEST_METHOD']!=='POST')tt_fail('POST required.',405,'Boost');tt_ad_check_csrf();$uid=(int)$_SESSION['id'];$post=max(0,(int)($_POST['post_id']??0));$credits=max(0,min(1000000,(int)($_POST['credits']??0)));$target=trim((string)($_POST['target_user']??''));$scope=trim((string)($_POST['target_scope']??'public'));$tags=trim((string)($_POST['target_tags']??''));$db=tt_db_open(false);tt_ad_require_schema($db);try{$db->begin_transaction();$bid=tt_ad_apply_boost($db,$uid,$post,$credits,$target,$scope,$tags);$db->commit();}catch(Throwable $e){@$db->rollback();$db->close();tt_fail('Could not apply ad credits: '.$e->getMessage(),400,'Boost');}$db->close();header('Location: post.php?boosted='.$bid.'#post-'.$post);exit;